 public static int Main(string[] args){try{
  var dll=Path.GetFullPath(args[0]);var resolver=new AssemblyDependencyResolver(dll);AssemblyLoadContext.Default.Resolving+=(_,name)=>resolver.ResolveAssemblyToPath(name) is { } p?AssemblyLoadContext.Default.LoadFromAssemblyPath(p):null;
