  void Invoke(string stage,Action action,Action<string,object?>? log){try{method.Invoke(null,[stage,action,log]);}catch(TargetInvocationException error)when(error.InnerException is not null){throw error.InnerException;}}
  foreach(var stage in new[]{"validation","assembly.load","assembly.configure","motherboard.collect","device.type","device.get-current","device.construct","device.initialize","device.identity"})Check(stage+": nested failure retains exact original exception and typed evidence",()=>{
   var original=Failure();var events=new List<(string Name,object? Value)>();Exception? caught=null;
   try{Invoke(stage,()=>throw original,(name,value)=>events.Add((name,value)));}catch(Exception error){caught=error;}
   Require(ReferenceEquals(original,caught),"original exception replaced");Require(events.Count==1&&events[0].Name=="hc.initialization.failure","missing/duplicated failure event");
   var json=JsonSerializer.Serialize(events[0].Value);using var doc=JsonDocument.Parse(json);var root=doc.RootElement;Require(root.GetProperty("stage").GetString()==stage&&root.GetProperty("phase").GetString()==stage,"stage missing");var chain=root.GetProperty("exceptionChain");Require(chain.GetArrayLength()==3,"nested root lost");Require(chain[1].GetProperty("typeInitializationType").GetString()=="HandheldCompanion.Managers.ManagerFactory","static type missing");Require(chain[2].GetProperty("exceptionType").GetString()==typeof(ArgumentException).FullName,"root exception missing");Require(chain[2].GetProperty("hResultHex").GetString()=="0x80070057","root HRESULT missing");Require(!json.Contains("inert-secret-message"),"exception message leaked");
  });
