  Check("absent logger preserves the original failure",()=>{var original=Failure();Exception? caught=null;try{Invoke("device.get-current",()=>throw original,null);}catch(Exception error){caught=error;}Require(ReferenceEquals(original,caught),"null log changed exception");});
