  bool? deployedHasStageHook=null;if(args.Length>2)Check("deployed identity is inspected as PE metadata without running it",()=>{using var stream=File.OpenRead(args[2]);using var pe=new PEReader(stream);var metadata=pe.GetMetadataReader();deployedHasStageHook=metadata.TypeDefinitions.Select(h=>metadata.GetTypeDefinition(h)).Where(t=>metadata.GetString(t.Name)=="RealHcBackend").SelectMany(t=>t.GetMethods()).Any(h=>metadata.GetString(metadata.GetMethodDefinition(h).Name)=="RunHcInitializationStage");Require(metadata.TypeDefinitions.Select(h=>metadata.GetTypeDefinition(h)).Count(t=>metadata.GetString(t.Name)=="RealHcBackend")==1,"deployed metadata target is missing or ambiguous");});
  foreach(var mode in new[]{"off","on","unreadable"})Check("initialization failure persists with detailed logging "+mode,()=>{
   var dir=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(args[1])!,"ledger-"+mode+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var logType=host.GetType("YeManFanHost.HostDiagnosticLog",true)!;var log=Activator.CreateInstance(logType,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,[dir,0],null)!;var write=logType.GetMethod("Write",BindingFlags.Public|BindingFlags.Instance)!;var flag=System.IO.Path.Combine(dir,"fan-logging-enabled.flag");FileStream? held=null;
   if(mode=="on")File.WriteAllText(flag,"enabled");else if(mode=="unreadable"){held=new FileStream(flag,FileMode.Create,FileAccess.ReadWrite,FileShare.None);held.Write("enabled"u8);held.Flush();}
   var original=Failure();try{try{Invoke("device.get-current",()=>throw original,(name,value)=>write.Invoke(log,[name,value]));}catch(Exception error){Require(ReferenceEquals(error,original),"logger changed failure");}}
   finally{held?.Dispose();}
   var fault=System.IO.Path.Combine(dir,"fan-host-fault.log");Require(File.Exists(fault),"initialization failure lost from default fault ledger");var records=File.ReadAllLines(fault);Require(records.Length==1,"duplicate failure rows");using var doc=JsonDocument.Parse(records[0]);Require(doc.RootElement.GetProperty("eventName").GetString()=="hc.initialization.failure","wrong event");Require(doc.RootElement.GetProperty("details").GetProperty("stage").GetString()=="device.get-current","stage missing on disk");Require(!records[0].Contains("inert-secret-message"),"secret message logged");var runtime=System.IO.Path.Combine(dir,"yeman-fan-host-runtime.log");Require(mode=="on"?File.Exists(runtime)&&File.ReadAllLines(runtime).Length==1:!File.Exists(runtime),"detailed runtime gate changed");
  });
  Check("success and ordinary detail remain quiet while logging is off",()=>{var dir=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(args[1])!,"quiet-"+Guid.NewGuid().ToString("N"));var logType=host.GetType("YeManFanHost.HostDiagnosticLog",true)!;var log=Activator.CreateInstance(logType,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,[dir,0],null)!;var write=logType.GetMethod("Write",BindingFlags.Public|BindingFlags.Instance)!;Invoke("device.initialize",()=>{},(name,value)=>write.Invoke(log,[name,value]));write.Invoke(log,["hc-operation.begin",new{operation="inert"}]);Require(Directory.GetFiles(dir,"*.log").Length==0,"success enabled log work");});
