 }catch(Exception error){Console.Error.WriteLine(error);return 2;}}
 static void ThrowRoot()=>throw new ArgumentException("inert secret value not for diagnostic output");
}
internal static class StaticCounter{public static int Calls;}
internal static class Poisoned{static Poisoned(){StaticCounter.Calls++;throw new ArgumentException("inert static failure");}public static void Touch(){}}
